//! AWS Redis: ElastiCache for Valkey replication group emitter.
//!
//! Mirrors the runtime Redis controller and the
//! CloudFormation emitter so the setup package and the live controller converge on the same
//! cloud resources: a dedicated security group admitting 6379 from workload groups only, a cache
//! subnet group, a parameter group with `maxmemory-policy`, an AUTH token in Secrets Manager, and
//! the replication group (Valkey, TLS and AUTH always on).
//!
//! The AUTH token is generated by Terraform's `random_password`, so it is in the Terraform
//! state (marked sensitive). ElastiCache has no service-managed token, unlike Aurora.

use alien_core::{
    import::EmitContext, ComputeCluster, ErrorData, KubernetesCluster, KubernetesClusterProvider,
    Network, NetworkSettings, Redis, ResourceLifecycle, Result,
};
use alien_error::AlienError;
use alien_permissions::BindingTarget;
use crate::block::{attr, resource_block};
use crate::emitters::aws::helpers::{
    aws_terraform_permission_context, downcast, emit_iam_role_policy_for_target_with_label,
    iam_policy_name_sanitize, nested_block, private_subnet_ids_expr, required_label,
    resource_prefix_template, security_group_ids_expr, tags, vpc_id_expr,
};
use crate::expr;
use crate::{TfEmitter, TfFragment};
use hcl::expr::Expression;

use super::postgres::{permission_owners, render_expression};

const REDIS_PORT: i64 = 6379;
/// Must equal the controller's `ENGINE_VERSION`, `PARAMETER_GROUP_FAMILY` and
/// `SNAPSHOT_RETENTION_DAYS` (pinned by the same constants in the CloudFormation emitter).
const ENGINE_VERSION: &str = "9.0";
const PARAMETER_GROUP_FAMILY: &str = "valkey9";
const SNAPSHOT_RETENTION_DAYS: i64 = 7;

#[derive(Debug, Clone, Copy, Default)]
pub struct AwsRedisEmitter;

impl TfEmitter for AwsRedisEmitter {
    fn emit(&self, ctx: &EmitContext<'_>) -> Result<TfFragment> {
        let redis = downcast::<Redis>(ctx, Redis::RESOURCE_TYPE)?;
        let (node_type, _) = redis.elasticache_node_type()?;
        let label = required_label(ctx)?;
        let key_arn = redis
            .encryption_key
            .as_ref()
            .map(|key| {
                ctx.name_for(key.id())
                    .map(|label| crate::emitters::aws::key::key_arn(label))
                    .ok_or_else(|| {
                        AlienError::new(ErrorData::GenericError {
                            message: format!(
                                "missing encryption Key '{}' for Redis '{}'",
                                key.id(),
                                redis.id
                            ),
                        })
                    })
            })
            .transpose()?;
        let mut fragment = TfFragment::default();

        fragment.resource_blocks.push(resource_block(
            "aws_security_group",
            label,
            [
                attr(
                    "name",
                    resource_prefix_template(&format!("{}-redis-sg", redis.id)),
                ),
                attr(
                    "description",
                    Expression::String("ElastiCache Redis security group".to_string()),
                ),
                attr("vpc_id", vpc_id_expr(ctx)),
                nested_block(
                    "egress",
                    vec![
                        attr("from_port", Expression::Number(hcl::Number::from(0i64))),
                        attr("to_port", Expression::Number(hcl::Number::from(0i64))),
                        attr("protocol", Expression::String("-1".to_string())),
                        attr(
                            "cidr_blocks",
                            Expression::Array(vec![Expression::String("0.0.0.0/0".to_string())]),
                        ),
                    ],
                ),
                attr("tags", tags(ctx, "redis")),
            ],
        ));

        // Ingress on 6379 from workload security groups only.
        let mut ingress_sources = Vec::new();
        let network_settings = ctx.stack.resources().find_map(|(_id, entry)| {
            entry
                .config
                .downcast_ref::<Network>()
                .map(|network| &network.settings)
        });
        if !matches!(network_settings, Some(NetworkSettings::UseDefault)) {
            let stack_sg_source = expr::raw(format!(
                "element({}, 0)",
                render_expression(&security_group_ids_expr(ctx))?
            ));
            let count = matches!(network_settings, Some(NetworkSettings::Create { .. }))
                .then_some("var.network_mode == \"use-default\" ? 0 : 1");
            ingress_sources.push((format!("{label}_ingress"), stack_sg_source, count));
        }
        let eks_cluster = ctx.stack.resources().find_map(|(id, entry)| {
            let cluster = entry.config.downcast_ref::<KubernetesCluster>()?;
            (cluster.provider == KubernetesClusterProvider::Eks).then_some(id)
        });
        if let Some(id) = eks_cluster {
            let name = ctx.name_for(id).ok_or_else(|| {
                AlienError::new(ErrorData::GenericError {
                    message: format!("missing Terraform label for resource '{id}'"),
                })
            })?;
            ingress_sources.push((
                format!("{label}_ingress_from_{name}"),
                expr::raw(format!(
                    "var.kubernetes_cluster_mode == \"create\" ? aws_eks_cluster.{name}[0].vpc_config[0].cluster_security_group_id : data.aws_eks_cluster.{name}_existing[0].vpc_config[0].cluster_security_group_id"
                )),
                None,
            ));
        }
        for (id, entry) in ctx.stack.resources() {
            if eks_cluster.is_none()
                && entry.lifecycle == ResourceLifecycle::Frozen
                && entry.config.downcast_ref::<ComputeCluster>().is_some()
            {
                let name = ctx.name_for(id).ok_or_else(|| {
                    AlienError::new(ErrorData::GenericError {
                        message: format!("missing Terraform label for resource '{id}'"),
                    })
                })?;
                ingress_sources.push((
                    format!("{label}_ingress_from_{name}"),
                    expr::traversal(["aws_security_group", name, "id"]),
                    None,
                ));
            }
        }
        for (ingress_label, source, count) in ingress_sources {
            let mut attributes = vec![
                attr("type", Expression::String("ingress".to_string())),
                attr("protocol", Expression::String("tcp".to_string())),
                attr(
                    "from_port",
                    Expression::Number(hcl::Number::from(REDIS_PORT)),
                ),
                attr("to_port", Expression::Number(hcl::Number::from(REDIS_PORT))),
                attr(
                    "security_group_id",
                    expr::traversal(["aws_security_group", label, "id"]),
                ),
                attr("source_security_group_id", source),
                attr(
                    "description",
                    Expression::String("Allow stack workloads to reach Redis on 6379".to_string()),
                ),
            ];
            if let Some(count) = count {
                attributes.insert(0, attr("count", expr::raw(count)));
            }
            fragment.resource_blocks.push(resource_block(
                "aws_security_group_rule",
                &ingress_label,
                attributes,
            ));
        }

        fragment.resource_blocks.push(resource_block(
            "aws_elasticache_subnet_group",
            label,
            [
                attr(
                    "name",
                    resource_prefix_template(&format!("{}-redis-subnets", redis.id)),
                ),
                attr("subnet_ids", private_subnet_ids_expr(ctx)),
                attr("tags", tags(ctx, "redis")),
            ],
        ));

        fragment.resource_blocks.push(resource_block(
            "aws_elasticache_parameter_group",
            label,
            [
                // The family is in the name so a new Valkey major can replace the group
                // (create_before_destroy) without a name clash.
                attr(
                    "name",
                    resource_prefix_template(&format!("{}-{PARAMETER_GROUP_FAMILY}", redis.id)),
                ),
                attr(
                    "family",
                    Expression::String(PARAMETER_GROUP_FAMILY.to_string()),
                ),
                attr(
                    "description",
                    Expression::String(format!("Valkey settings for Redis '{}'", redis.id)),
                ),
                nested_block(
                    "parameter",
                    vec![
                        attr("name", Expression::String("maxmemory-policy".to_string())),
                        attr(
                            "value",
                            Expression::String(redis.eviction_policy.as_str().to_string()),
                        ),
                    ],
                ),
                nested_block(
                    "lifecycle",
                    vec![attr("create_before_destroy", Expression::Bool(true))],
                ),
                attr("tags", tags(ctx, "redis")),
            ],
        ));

        // The token is generated ephemerally and handed to Secrets Manager and ElastiCache
        // through write-only arguments, so it never enters Terraform state. Bump the revision
        // variable to rotate it; keep it unchanged when retrying an interrupted apply.
        let revision =
            crate::emitters::postgres_credentials::password_revision(&mut fragment, label);
        fragment.resource_blocks.push(resource_block(
            "aws_secretsmanager_secret",
            &format!("{label}_auth"),
            [
                attr(
                    "name",
                    resource_prefix_template(&format!("{}-auth", redis.id)),
                ),
                attr(
                    "description",
                    Expression::String(format!("Redis AUTH token for '{}'", redis.id)),
                ),
                // Match the controller: deleting the resource deletes the token at once.
                attr(
                    "recovery_window_in_days",
                    Expression::Number(hcl::Number::from(0i64)),
                ),
                attr("tags", tags(ctx, "redis")),
            ],
        ));
        // The saved version is the authority: ElastiCache reads it back, so a retry after the
        // secret write succeeded but the replication group failed uses the same token.
        fragment
            .ephemeral_blocks
            .push(crate::block::ephemeral_block(
                "aws_secretsmanager_secret_version",
                &format!("{label}_auth"),
                [
                    attr(
                        "secret_id",
                        expr::traversal([
                            "aws_secretsmanager_secret",
                            &format!("{label}_auth"),
                            "id",
                        ]),
                    ),
                    attr(
                        "version_id",
                        expr::traversal([
                            "aws_secretsmanager_secret_version",
                            &format!("{label}_auth"),
                            "version_id",
                        ]),
                    ),
                ],
            ));
        fragment.resource_blocks.push(resource_block(
            "aws_secretsmanager_secret_version",
            &format!("{label}_auth"),
            [
                attr(
                    "secret_id",
                    expr::traversal(["aws_secretsmanager_secret", &format!("{label}_auth"), "id"]),
                ),
                attr(
                    "secret_string_wo",
                    crate::emitters::postgres_credentials::generated_password(label),
                ),
                attr("secret_string_wo_version", revision),
            ],
        ));

        fragment.resource_blocks.push(resource_block(
            "aws_elasticache_replication_group",
            label,
            [
                attr("replication_group_id", resource_prefix_template(&redis.id)),
                attr(
                    "description",
                    Expression::String(format!("Alien Redis '{}'", redis.id)),
                ),
                attr("engine", Expression::String("valkey".to_string())),
                attr(
                    "engine_version",
                    Expression::String(ENGINE_VERSION.to_string()),
                ),
                attr("node_type", Expression::String(node_type.to_string())),
                attr(
                    "num_cache_clusters",
                    Expression::Number(hcl::Number::from(if redis.high_availability {
                        2i64
                    } else {
                        1i64
                    })),
                ),
                attr(
                    "automatic_failover_enabled",
                    Expression::Bool(redis.high_availability),
                ),
                attr(
                    "multi_az_enabled",
                    Expression::Bool(redis.high_availability),
                ),
                attr(
                    "parameter_group_name",
                    expr::traversal(["aws_elasticache_parameter_group", label, "name"]),
                ),
                attr(
                    "subnet_group_name",
                    expr::traversal(["aws_elasticache_subnet_group", label, "name"]),
                ),
                attr(
                    "security_group_ids",
                    Expression::Array(vec![expr::traversal(["aws_security_group", label, "id"])]),
                ),
                attr("transit_encryption_enabled", Expression::Bool(true)),
                attr(
                    "transit_encryption_mode",
                    Expression::String("required".to_string()),
                ),
                attr("at_rest_encryption_enabled", Expression::Bool(true)),
                attr("kms_key_id", key_arn.unwrap_or(Expression::Null)),
                attr(
                    "auth_token_wo",
                    expr::traversal([
                        "ephemeral",
                        "aws_secretsmanager_secret_version",
                        &format!("{label}_auth"),
                        "secret_string",
                    ]),
                ),
                // Follows the saved version, so a rotated or recreated secret updates the token.
                attr(
                    "auth_token_wo_version",
                    crate::emitters::postgres_credentials::database_revision(&format!(
                        "aws_secretsmanager_secret_version.{label}_auth.version_id"
                    )),
                ),
                attr(
                    "snapshot_retention_limit",
                    Expression::Number(hcl::Number::from(if redis.persistence {
                        SNAPSHOT_RETENTION_DAYS
                    } else {
                        0
                    })),
                ),
                attr("apply_immediately", Expression::Bool(true)),
                attr("tags", tags(ctx, "redis")),
            ],
        ));
        emit_redis_iam(ctx, &mut fragment, label)?;

        // Setup owns the cache; uninstall leaves it, like the other clouds. Keep what the data
        // needs: the replication group, its AUTH-token secret (without it the data is
        // unreachable), and the subnet group, parameter group and security group, which AWS
        // refuses to delete while the group exists. Ingress rules are not kept: they reference
        // the workload security group and go with the other access grants.
        fragment.retain_resources(|kind, name| {
            matches!(
                kind,
                "aws_elasticache_replication_group"
                    | "aws_elasticache_subnet_group"
                    | "aws_elasticache_parameter_group"
                    | "aws_security_group"
            ) || (kind == "aws_secretsmanager_secret" && name == format!("{label}_auth"))
        });
        // The token version rotates by replacement; guard the parent secret, not the version.
        fragment.retain_state(|kind, _| kind == "aws_secretsmanager_secret_version");
        Ok(fragment)
    }

    fn emit_import_ref(&self, ctx: &EmitContext<'_>) -> Result<Expression> {
        let redis = downcast::<Redis>(ctx, Redis::RESOURCE_TYPE)?;
        let (node_type, _) = redis.elasticache_node_type()?;
        let label = required_label(ctx)?;
        Ok(expr::object([
            (
                "replicationGroupId",
                expr::traversal(["aws_elasticache_replication_group", label, "id"]),
            ),
            (
                "subnetGroupName",
                expr::traversal(["aws_elasticache_subnet_group", label, "name"]),
            ),
            (
                "securityGroupId",
                expr::traversal(["aws_security_group", label, "id"]),
            ),
            (
                "parameterGroupName",
                expr::traversal(["aws_elasticache_parameter_group", label, "name"]),
            ),
            (
                "authSecretArn",
                expr::traversal(["aws_secretsmanager_secret", &format!("{label}_auth"), "arn"]),
            ),
            (
                "endpoint",
                expr::traversal([
                    "aws_elasticache_replication_group",
                    label,
                    "primary_endpoint_address",
                ]),
            ),
            ("port", Expression::Number(hcl::Number::from(REDIS_PORT))),
            ("nodeType", Expression::String(node_type.to_string())),
            (
                "engineVersion",
                Expression::String(ENGINE_VERSION.to_string()),
            ),
            (
                "highAvailability",
                Expression::Bool(redis.high_availability),
            ),
        ]))
    }

    fn emit_binding_ref(&self, ctx: &EmitContext<'_>) -> Result<Option<Expression>> {
        let label = required_label(ctx)?;
        Ok(Some(expr::object([
            ("service", Expression::String("elasticache".to_string())),
            (
                "host",
                expr::traversal([
                    "aws_elasticache_replication_group",
                    label,
                    "primary_endpoint_address",
                ]),
            ),
            ("port", Expression::Number(hcl::Number::from(REDIS_PORT))),
            ("username", Expression::String("default".to_string())),
            (
                "passwordSecretArn",
                expr::traversal(["aws_secretsmanager_secret", &format!("{label}_auth"), "arn"]),
            ),
        ])))
    }
}

/// `redis/*` IAM each owner holds: workloads get `redis/data-access` (read the AUTH secret),
/// management gets `redis/heartbeat`. Never the ownership set.
fn emit_redis_iam(ctx: &EmitContext<'_>, fragment: &mut TfFragment, label: &str) -> Result<()> {
    for (owner_label, permission_refs) in permission_owners(ctx, "redis/") {
        let context = aws_terraform_permission_context()
            .with_resource_name(ctx.resource_id.to_string())
            .with_resource_id(format!("${{aws_secretsmanager_secret.{label}_auth.arn}}"));
        for (idx, permission_ref) in permission_refs.iter().enumerate() {
            let Some(permission_set) =
                permission_ref.resolve(|name| alien_permissions::get_permission_set(name).cloned())
            else {
                continue;
            };
            if !permission_set.id.starts_with("redis/") || permission_set.id.ends_with("/provision")
            {
                continue;
            }
            let policy_label = format!(
                "{label}_{owner_label}_{}_{idx}",
                iam_policy_name_sanitize(&permission_set.id)
            );
            let policy_name = iam_policy_name_sanitize(&format!(
                "{}-{}-{idx}",
                ctx.resource_id, permission_set.id
            ));
            emit_iam_role_policy_for_target_with_label(
                fragment,
                &owner_label,
                &permission_set,
                &policy_label,
                &policy_name,
                &context,
                BindingTarget::Resource,
            )?;
        }
    }
    Ok(())
}
